<?php
declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';$user=require_role('admin');$rows=db()->query("SELECT u.id,u.full_name,GROUP_CONCAT(DISTINCT c.nama_kelas ORDER BY c.nama_kelas SEPARATOR ', ') classes,COUNT(DISTINCT s.id) students,COUNT(DISTINCT CASE WHEN d.tanggal=CURDATE() THEN d.student_id END) reports_today,COUNT(DISTINCT CASE WHEN d.tanggal>=DATE_SUB(CURDATE(),INTERVAL 6 DAY) THEN d.id END) reports_week,COUNT(DISTINCT e.id) exams,COUNT(DISTINCT m.id) munaqosyah FROM users u LEFT JOIN classes c ON c.teacher_id=u.id AND c.aktif=1 LEFT JOIN students s ON s.teacher_id=u.id AND s.status='aktif' LEFT JOIN daily_student_reports d ON d.teacher_id=u.id LEFT JOIN level_promotion_exams e ON e.teacher_id=u.id LEFT JOIN munaqosyah_exams m ON m.teacher_id=u.id WHERE u.role='guru' AND u.is_active=1 GROUP BY u.id ORDER BY u.full_name")->fetchAll();$pageTitle='Kelengkapan Laporan';require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><p class="eyebrow">Pengendalian Mutu</p><h1 class="page-title">Kelengkapan Laporan</h1><p class="page-description">Bandingkan jumlah siswa dengan laporan Guru hari ini dan aktivitas penilaian lainnya.</p></div></div><section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Guru</th><th>Kelas</th><th>Laporan Hari Ini</th><th>7 Hari</th><th>Ujian Level</th><th>Munaqosyah</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $row):$percent=(int)$row['students']?min(100,round((int)$row['reports_today']/(int)$row['students']*100)):0;?><tr><td class="name"><?= e($row['full_name']) ?><br><small class="muted"><?= (int)$row['students'] ?> siswa</small></td><td><?= e($row['classes']?:'Belum ada kelas') ?></td><td><strong><?= (int)$row['reports_today'] ?>/<?= (int)$row['students'] ?></strong><div class="progress"><span style="width:<?= $percent ?>%"></span></div></td><td><?= (int)$row['reports_week'] ?> laporan</td><td><?= (int)$row['exams'] ?></td><td><?= (int)$row['munaqosyah'] ?></td><td><span class="badge <?= $percent>=90?'badge-green':($percent>=50?'badge-yellow':'badge-red') ?>"><?= $percent>=90?'Lengkap':($percent>=50?'Perlu dicek':'Belum lengkap') ?></span></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7"><div class="empty"><strong>Belum ada Guru aktif</strong>Data kelengkapan akan tampil setelah akun Guru tersedia.</div></td></tr><?php endif;?></tbody></table></div></section><?php require ROOT_PATH.'/includes/footer.php';?>

